sys_script_include.script:
var OpenAIUtility = Class.create();

OpenAIUtility.token = gs.getProperty("x_edpet_open_ai.bearer_token");
OpenAIUtility.boundary = gs.getProperty("x_edpet_open_ai.file_upload_boundary");
OpenAIUtility.tools = [{ "type": "file_search" }, { "type": "code_interpreter" }];
OpenAIUtility.model = gs.getProperty("x_edpet_open_ai.model");
OpenAIUtility.default_vectore_store_id = gs.getProperty("x_edpet_open_ai.default_vector_store_id");


OpenAIUtility.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


	logError: function (message) {
		gs.info("OPEN AI ERROR: " + message);
	},

	uploadFileToOpenAi: function (attachmentId) {
		try{
			var mpHelper = new x_edpet_open_ai.MultipartHelper();
			var userGR = new GlideRecord("sys_user");
			if (userGR.get(gs.getUserID())) {
				mpHelper.setHostRecord(userGR);
			}

			mpHelper.addAttachment('file', attachmentId);
			mpHelper.createBody({ purpose: "assistants" });

			var restMessage = new sn_ws.RESTMessageV2();
			restMessage.setEndpoint('https://api.openai.com/v1/files');
			restMessage.setHttpMethod('POST');
			restMessage.setRequestHeader("File", 'filename');
			restMessage.setRequestBody({ purpose: 'assistants' });
			restMessage.setRequestHeader("Multipart", "true");
			restMessage.setRequestHeader('Content-Type', mpHelper.getContentType());
			restMessage.setRequestHeader('Authorization', "Bearer "+ OpenAIUtility.token);
			restMessage.setRequestBodyFromAttachment(mpHelper.getBodyId());

			var restResponse = restMessage.execute();
			mpHelper.deleteBody();

			var response = restResponse.getBody();
			var httpStatus = JSON.parse(response).status;

			var fileId = JSON.parse(response).id;

			gs.info("uploadFileToOpenAi MANJO httpStatus == "+ httpStatus);
			gs.info("uploadFileToOpenAi MANJO == "+ response);


			return {
				"status": httpStatus,
				"response": fileId
			};

		}catch(error){
			return {
				"status": "error",
				"response": error
			};
		}
	},

	getAssistant: function (intentSysId) {
		var intentGr = new GlideRecord("x_edpet_open_ai_intent");
		if (intentGr.get(intentSysId)) {
			var assistantGr = intentGr.assistant.getRefRecord();
			return assistantGr;
		}
	},

	getIntent: function (intentSysId) {
		var intentGr = new GlideRecord("x_edpet_open_ai_intent");
		if (intentGr.get(intentSysId)) {
			return intentGr;
		}
	},

	createAssistant: function (name, instructions, temperature, model) {
		var r = new sn_ws.RESTMessageV2('x_edpet_open_ai.Open AI v1', 'Create Assistant');
		r.setStringParameterNoEscape('temperature', temperature);
		r.setStringParameterNoEscape('name', name);
		r.setStringParameterNoEscape('tools', JSON.stringify(OpenAIUtility.tools));
		r.setStringParameterNoEscape('model', model);
		// r.setStringParameterNoEscape('description', 'Test Description');
		r.setStringParameterNoEscape('bearer_token', OpenAIUtility.token);
		r.setStringParameterNoEscape('instructions', instructions);
		var response = r.execute();
		var responseBody = JSON.parse(response.getBody());
		// gs.addInfoMessage("ID == "+ JSON.parse(responseBody).id);

		return responseBody;
	},

createThreadAndRun: function (intentSysId, messagesToIntent, uploadedFiles = []) {
	try{

		gs.info("messagesToIntent == "+messagesToIntent);


		///END
		var files = [];
		uploadedFiles.forEach(function(att){
			files.push({"file_id": att, "tools": [{ "type": "file_search" }, { "type": "code_interpreter" }]});
		});
		var intentGr = this.getIntent(intentSysId);
		var assistantGr = intentGr.assistant.getRefRecord();

		var restMessage = new sn_ws.RESTMessageV2('x_edpet_open_ai.Open AI v1', 'Create thread and run');
		restMessage.setStringParameterNoEscape('tools', JSON.stringify(OpenAIUtility.tools));
		restMessage.setStringParameterNoEscape('assistant_id', assistantGr.getValue("gpt_assistant_id"));
		restMessage.setStringParameterNoEscape('bearer_token', OpenAIUtility.token);
		restMessage.setStringParameterNoEscape('instructions', intentGr.getValue("system_intent"));
		// restMessage.setStringParameterNoEscape('instructions', "one of the attached file contains JSON. from the JSON properties follow and do whats written as the value of 'system_intent'");
		restMessage.setStringParameterNoEscape('model', 'gpt-4o');
		var messages = [
			{ role: "user", content: messagesToIntent}
		];
		// messagesToIntent.forEach(function(ms){
		// 	 messages.push(
		// 		{ role: "user", content: "who are you"},
		// 	);
		// });

		gs.info("messages after == "+messages);


		if (files.length > 0) {
			messages[0].attachments = files;
		}
		restMessage.setStringParameterNoEscape('messages', JSON.stringify(messages));

		var response = restMessage.execute();
		var responseBody = response.getBody();
		var httpStatus = response.getStatusCode();

		gs.info("createThreadAndRun MANJO httpStatus == "+ httpStatus);
		gs.info("createThreadAndRun MANJO responseBody == "+ JSON.stringify(responseBody));


		return {
			"status": httpStatus,
			"response": responseBody
		};

	}catch(error){
		gs.info("createThreadAndRun MANJO ERROR == "+ error);
		return {
				"status": "error",
				"response": error
			};
	}

	},

	createThreadAndRunWithOutFile: function (intentSysId, messageToIntent) {

		var intentGr = this.getIntent(intentSysId);
		var assistantGr = intentGr.assistant.getRefRecord();

		var restMessage = new sn_ws.RESTMessageV2('x_edpet_open_ai.Open AI v1', 'Create thread and run');
		restMessage.setStringParameterNoEscape('tools', JSON.stringify(OpenAIUtility.tools));
		restMessage.setStringParameterNoEscape('assistant_id', "asst_u2uXOGUvkDNL4zIakk3ITQTp");
		restMessage.setStringParameterNoEscape('bearer_token', OpenAIUtility.token);

		// gs.info("before == "+intentGr.getValue("system_intent"));

		// var after =this.makeGoodString(intentGr.getValue("system_intent"));
		// gs.info("after == "+ after);

		// restMessage.setStringParameterNoEscape('instructions', after);

		var instruction = intentGr.getValue("system_intent");

		restMessage.setStringParameterNoEscape('instructions', instruction);

		restMessage.setStringParameterNoEscape('model', 'gpt-4o');
		var messages = [
			{ "role": "user", "content": messageToIntent}
		];

		restMessage.setStringParameterNoEscape('messages', JSON.stringify(messages));

		var response = restMessage.execute();
		var responseBody = response.getBody();
		var httpStatus = response.getStatusCode();
		return responseBody;
	},

	makeGoodString: function (input) {
 let sanitizedString = input.trim();

    // 2. Replace escaped characters with their proper equivalents
    sanitizedString = sanitizedString
      .replace(/\\n/g, "\n") // Convert escaped newlines to actual newlines
      .replace(/\\t/g, "\t") // Convert escaped tabs to actual tabs
      .replace(/\\"/g, '"')  // Replace escaped double quotes
      .replace(/\\'/g, "'")  // Replace escaped single quotes
      .replace(/\\\\/g, "\\"); // Replace double backslashes with a single backslash

    // 3. Escape backticks for template literal safety
    sanitizedString = sanitizedString.replace(/`/g, "\\`");

    // 4. Wrap the string in backticks to convert it into a template literal
    sanitizedString = `\`${sanitizedString}\``;

    return sanitizedString;
},

