	retrieveAssistantMessage: function (threadId, attempts = 0) {
    try {
		// threadId = "thread_ZH1RLyKJlp8Pm7bibyVU2Rzl";
        gs.info("retrieveAssistantMessage threadId == " + threadId);
        gs.info("retrieveAssistantMessage attempts == " + attempts);

        // Stop if maximum attempts (5) are reached
        if (attempts >= 11) {
            return {
                "status": 200,
                "response": []
            };
        }

        // Perform the REST API call
        var r = new sn_ws.RESTMessageV2('x_edpet_open_ai.Open AI v1', 'List messages');
        r.setStringParameterNoEscape('thread_id', threadId);
        r.setStringParameterNoEscape('bearer_token', OpenAIUtility.token);
        var response = r.execute();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        var messages = JSON.parse(responseBody).data;
        var assistantMessages = messages.filter(msg => msg.role == "assistant");

        gs.info("retrieveAssistantMessage MANJO httpStatus== " + httpStatus);
        gs.info("retrieveAssistantMessage MANJO assistantMessages== " + JSON.stringify(assistantMessages));
        gs.info("retrieveAssistantMessage assistantMessages.length == " + assistantMessages.length);

        // If there are assistant messages, return them
        if (assistantMessages.length > 0 && assistantMessages[0].content.length > 0) {
            return {
                "status": httpStatus,
                "response": assistantMessages
            };
        } else {
            gs.info("retrieveAssistantMessage inside loop 1");
			var startTime = new Date().getTime();
				var delay = 9000;
				while (new Date().getTime() < startTime + delay){
				//
				};
					return this.retrieveAssistantMessage(threadId, attempts + 1);  
        }
    } catch (error) {
        gs.info("retrieveAssistantMessage MANJO == " + error);
        return {
            "status": "error",
            "response": error
        };
    }
},



	addMessagetoThread: function (intentSysId, threadId, attachments) {
		var files = [];
		attachments.forEach(attachment => {
			files.push({
				"file_id": attachment,
				"tools": OpenAIUtility.tools
			});
		});
		var intentGr = this.getIntent(intentSysId);
		var r = new sn_ws.RESTMessageV2('x_edpet_open_ai.Open AI v1', 'Add a Message to the Thread');
		r.setStringParameterNoEscape('bearer_token', OpenAIUtility.token);
		r.setStringParameterNoEscape('role', 'user');
		r.setStringParameterNoEscape('content', intentGr.getValue("system_intent"));
		r.setStringParameterNoEscape('thread_id', threadId);
		r.setStringParameterNoEscape('attachments',
			[
				{
					"file_id": attachments,
					"tools": [{ "type": "file_search" }]
				}
			]
		);
		var response = r.execute();
		var responseBody = response.getBody();
		var httpStatus = response.getStatusCode();
		return responseBody;
	},

	createRun: function (intentSysId, assistantId, threadId) {
		var intentGr = this.getIntent(intentSysId);
		var r = new sn_ws.RESTMessageV2('x_edpet_open_ai.Open AI v1', 'Create a Run');
		r.setStringParameterNoEscape('bearer_token', OpenAIUtility.token);
		r.setStringParameterNoEscape('instructions', intentGr.getValue("system_intent"));
		r.setStringParameterNoEscape('thread_id', threadId);
		r.setStringParameterNoEscape('assistant_id', assistantId);
		var response = r.execute();
		var responseBody = response.getBody();
		return responseBody;
	},



	//check if there is atleast one vector store available, must populate "x_edpet_open_ai.vector_store_id" system property  with a default vactor store ID
	checkVectorStoreAvailability: function () {
		var r = new sn_ws.RESTMessageV2('x_edpet_open_ai.Open AI v1', 'List vector stores');
		r.setStringParameterNoEscape('bearer_token', this.token);
		var response = r.execute();
		var stores = JSON.parse(response.getBody());
		if (stores.data.length > 0) {
			return true;
		} else {
			return false;
		}
	},


	type: 'OpenAIUtility'
});
